-- Default-disabled fixed-operation adapter. No caller SQL or registration API.
begin;
create role privacy_content_executor nologin noinherit nosuperuser nocreatedb nocreaterole nobypassrls;
create role privacy_restore_executor nologin noinherit nosuperuser nocreatedb nocreaterole nobypassrls;
create role privacy_runtime_owner nologin noinherit nosuperuser nocreatedb nocreaterole nobypassrls;
create table public.privacy_runtime_operations(operation_id text primary key,body text not null,arity integer not null,mode text not null check(mode in ('rows','command','stream')),restore_only boolean not null,requires_scope boolean not null);
revoke all on public.privacy_runtime_operations from public,anon,authenticated,service_role,usage_executor,privacy_content_executor,privacy_restore_executor;
create trigger runtime_operations_immutable before update or delete on public.privacy_runtime_operations for each row execute function public.catalog_reject_mutation();
create trigger runtime_operations_no_truncate before truncate on public.privacy_runtime_operations for each statement execute function public.catalog_reject_mutation();
create function public.privacy_runtime_columns() returns table(table_name name,column_name name,data_type character varying,udt_name name,ordinal_position integer) language sql security definer set search_path=pg_catalog as $$
 select c.relname,a.attname,(case when t.typelem<>0 and t.typlen=-1 then 'ARRAY' when ntype.nspname<>'pg_catalog' then 'USER-DEFINED' else format_type(t.oid,null) end)::character varying,t.typname,a.attnum::integer from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace join pg_type t on t.oid=a.atttypid join pg_namespace ntype on ntype.oid=t.typnamespace where n.nspname='public' and c.relkind in ('r','p','v','m','f') and a.attnum>0 and not a.attisdropped
$$;
alter function public.privacy_runtime_columns() owner to privacy_runtime_owner;
revoke all on function public.privacy_runtime_columns() from public,anon,authenticated,service_role;
grant execute on function public.privacy_runtime_columns() to privacy_runtime_owner;
create function public.privacy_runtime_contact_available(p_account uuid) returns boolean language sql security definer set search_path=pg_catalog as $$ select exists(select 1 from auth.users u where u.id=p_account and u.deleted_at is null) $$;
alter function public.privacy_runtime_contact_available(uuid) owner to postgres;
revoke all on function public.privacy_runtime_contact_available(uuid) from public,anon,authenticated,service_role;
grant execute on function public.privacy_runtime_contact_available(uuid) to privacy_runtime_owner;
grant usage on schema public to privacy_runtime_owner;

-- A forged GUC alone grants nothing: every deletion checks the live DB lease,
-- subject, accepted scope and per-session membership again under RLS.
create function public.privacy_runtime_scope(p_job uuid,p_lease uuid) returns void language plpgsql security definer set search_path=pg_catalog as $$
begin
 if session_user not in ('privacy_content_executor','privacy_restore_executor') or current_setting('role',true)<>'none' then raise exception 'scope denied' using errcode='42501'; end if;
 if not exists(select 1 from public.privacy_content_jobs where id=p_job and lease_id=p_lease and state='running' and lease_until>clock_timestamp()) then raise exception 'stale scope' using errcode='42501'; end if;
 perform set_config('c15.runtime.job',p_job::text,true);perform set_config('c15.runtime.lease',p_lease::text,true);
end $$;
create function public.privacy_runtime_allows(p_account uuid,p_session uuid) returns boolean language sql security definer set search_path=pg_catalog as $$
 select (session_user='privacy_restore_executor' and exists(select 1 from public.privacy_restore_state where required and not ready) and (exists(select 1 from public.privacy_restored_subjects where account_id=p_account) or (p_session is not null and exists(select 1 from public.privacy_restored_sessions where account_id=p_account and session_id=p_session)))) or exists(select 1 from public.privacy_content_jobs j where j.id=nullif(current_setting('c15.runtime.job',true),'')::uuid and j.lease_id=nullif(current_setting('c15.runtime.lease',true),'')::uuid and j.account_id=p_account and j.state='running' and j.lease_until>clock_timestamp() and ((j.kind='account' and exists(select 1 from public.privacy_deletion_requests r where r.request_id=j.id and r.account_id=p_account and r.state='accepted_restricted')) or (j.kind='session' and j.resource_id=p_session) or (j.kind='history' and exists(select 1 from public.privacy_erased_sessions e where e.job_id=j.id and e.account_id=p_account and e.session_id=p_session))))
$$;
alter function public.privacy_runtime_scope(uuid,uuid) owner to privacy_runtime_owner;
alter function public.privacy_runtime_allows(uuid,uuid) owner to privacy_runtime_owner;
revoke all on function public.privacy_runtime_scope(uuid,uuid),public.privacy_runtime_allows(uuid,uuid) from public,anon,authenticated,service_role,usage_executor;
grant execute on function public.privacy_runtime_scope(uuid,uuid) to privacy_content_executor,privacy_restore_executor;
