do $$ declare n text; t text; begin foreach t in array array['privacy_lifecycle_audit'] loop n:=pg_get_serial_sequence('public.'||t,'id'); if n is not null then execute format('grant usage,select on sequence %s to privacy_runtime_owner',n); end if; end loop; end $$;
grant select on public.privacy_runtime_operations to privacy_runtime_owner;
grant update on public.privacy_deletion_requests,public.privacy_content_jobs to privacy_runtime_owner;
grant execute on function public.privacy_restore_accessible(),public.privacy_capture_erasure_keys(uuid,uuid),public.privacy_email_denied(text),public.subscription_auto_finish_slice(uuid,timestamptz) to privacy_runtime_owner;
             lease_until=clock_timestamp()+interval ''30 seconds'',attempts=attempts+1,revision=revision+1
             where id=(select id from privacy_content_jobs where
             (state=''pending'' or state=''running'' and lease_until<clock_timestamp())
             and retry_at<=clock_timestamp() and attempts<5 order by created_at for update skip locked limit 1)
             returning id,account_id,kind,resource_id,state,lease_id,artifact_key,progress,blockers) select coalesce(jsonb_agg(jsonb_build_array(c15_row.f0,c15_row.f1,c15_row.f2,c15_row.f3,c15_row.f4,c15_row.f5,c15_row.f6,c15_row.f7,c15_row.f8)), ''[]''::jsonb) from c15_row',1,'rows',false,false);
          select c15_auth.users_oid() union
          select f.conrelid from pg_constraint f join linked p on p.oid=f.confrelid
          where f.contype=''f''
        ) select c.relname from linked l join pg_class c on c.oid=l.oid
          join pg_namespace n on n.oid=c.relnamespace where n.nspname=''public'') c15_row(f0)',0,'rows',false,false);
grant update(active,fence) on public.subscription_auto_runs to privacy_runtime_owner;
grant usage on schema storage to privacy_runtime_owner;
grant select(bucket_id,name) on storage.objects to privacy_runtime_owner;
create policy c15_runtime_object_read on storage.objects for select to privacy_runtime_owner using(bucket_id='resumes' and public.privacy_runtime_allows((split_part(name,'/',1))::uuid,null::uuid));
grant select,insert on public.privacy_restored_replays to privacy_runtime_owner;
create policy c15_runtime_owner on public.privacy_restored_replays to privacy_runtime_owner using(true) with check(true);
grant delete on public.subscription_relay_connections to privacy_runtime_owner;
create policy c15_runtime_relay_delete_scope on public.subscription_relay_connections as restrictive for delete to privacy_runtime_owner using(public.privacy_runtime_allows(account_id,null::uuid));
create policy c15_runtime_email_delete_scope on public.outbound_email_events as restrictive for delete to privacy_runtime_owner using(email_type not like 'billing_%' and public.privacy_runtime_allows(user_id,null::uuid));
create function public.privacy_runtime_call(p_action text,p_operation text,p_args jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$
declare op public.privacy_runtime_operations; result jsonb; n bigint; row record; rows jsonb:='[]'; portal refcursor:='c15_runtime_snapshot'; begin
 if session_user not in ('privacy_content_executor','privacy_restore_executor') or current_setting('role',true)<>'none' then raise exception 'runtime denied' using errcode='42501'; end if;
 if p_action='fetch' then
  for i in 1..16 loop fetch portal into row; exit when not found; rows:=rows||jsonb_build_array(jsonb_build_array(row.category,row.document)); end loop;
  return jsonb_build_object('rows',rows,'count',jsonb_array_length(rows));
 elsif p_action='close' then close portal; return '{}'::jsonb;
 end if;
 select * into strict op from public.privacy_runtime_operations where operation_id=p_operation;
 if op.restore_only and session_user<>'privacy_restore_executor' then raise exception 'restore operation denied' using errcode='42501'; end if;
 if op.requires_scope and not exists(select 1 from public.privacy_content_jobs j where j.id=nullif(current_setting('c15.runtime.job',true),'')::uuid and j.lease_id=nullif(current_setting('c15.runtime.lease',true),'')::uuid and j.state='running' and j.lease_until>clock_timestamp()) then raise exception 'live scope required' using errcode='42501'; end if;
 if jsonb_typeof(p_args)<>'array' or jsonb_array_length(p_args)<>op.arity or octet_length(p_args::text)>2097152 then raise exception 'invalid operation parameters' using errcode='22023'; end if;
 if op.mode='stream' and p_action='open' then open portal for execute op.body using p_args; return '{}'::jsonb; end if;
 if p_action<>'execute' or op.mode='stream' then raise exception 'operation denied' using errcode='42501'; end if;
 if op.mode='rows' then execute op.body into result using p_args; n:=jsonb_array_length(result);
 else execute op.body using p_args; get diagnostics n=row_count; result:='[]'; end if;
 if octet_length(result::text)>2097152 then raise exception 'result bound exceeded' using errcode='54000'; end if;
 return jsonb_build_object('rows',result,'count',n);
end $$;
alter function public.privacy_runtime_call(text,text,jsonb) owner to privacy_runtime_owner;
revoke all on function public.privacy_runtime_call(text,text,jsonb) from public,anon,authenticated,service_role,usage_executor,privacy_cleanup_executor,privacy_preparation_executor;
grant execute on function public.privacy_runtime_call(text,text,jsonb) to privacy_content_executor,privacy_restore_executor;
commit;
